'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);

const N = Number(input[0]);
const F = Number(input[1]);
const grid = input.slice(2, 2 + N).map(row => row.split(''));
const visited = new Uint8Array(N * N);
const queue = new Int32Array(N * N);

let head = 0;
let tail = 0;

if (grid[0][0].charCodeAt(0) - 48 <= F) {
  visited[0] = 1;
  grid[0][0] = '*';
  queue[tail++] = 0;
}

while (head < tail) {
  const pos = queue[head++];
  const r = Math.floor(pos / N);
  const c = pos % N;

  if (r > 0) {
    const next = pos - N;
    if (!visited[next] && grid[r - 1][c].charCodeAt(0) - 48 <= F) {
      visited[next] = 1;
      grid[r - 1][c] = '*';
      queue[tail++] = next;
    }
  }
  if (r + 1 < N) {
    const next = pos + N;
    if (!visited[next] && grid[r + 1][c].charCodeAt(0) - 48 <= F) {
      visited[next] = 1;
      grid[r + 1][c] = '*';
      queue[tail++] = next;
    }
  }
  if (c > 0) {
    const next = pos - 1;
    if (!visited[next] && grid[r][c - 1].charCodeAt(0) - 48 <= F) {
      visited[next] = 1;
      grid[r][c - 1] = '*';
      queue[tail++] = next;
    }
  }
  if (c + 1 < N) {
    const next = pos + 1;
    if (!visited[next] && grid[r][c + 1].charCodeAt(0) - 48 <= F) {
      visited[next] = 1;
      grid[r][c + 1] = '*';
      queue[tail++] = next;
    }
  }
}

process.stdout.write(grid.map(row => row.join('')).join('\n'));
